// @reliability: normal
//! @ai: assisted
//! Cirrus bindings to the Volar spec's hash/cipher + VOLE API (H6 of
//! `docs/hash-cipher-generic-plan.md`).
//!
//! Cirrus (`portal-hot/cirrus`, the low-spec-target circuit compiler — RISC-V /
//! Arm Cortex-M symbolic executors) consumes `volar_spec::vole` directly via a
//! git pin, so it drifts whenever the spec's API changes. This module is the
//! **autogenerated-facing seam**: it re-exports exactly the spec surface Cirrus
//! depends on, with the hash/cipher backends selected for its targets, and a
//! drift-check test (below) recomputes a digest of the backing sources and
//! fails when they change — the signal to regenerate Cirrus's side.
//!
//! The bindings module's *compilation* is itself the first drift check: a
//! renamed/removed spec module fails `pub use` here. The digest test catches
//! the subtler case (a signature/behavior change to an existing module).

use super::*;

// --- The hash/cipher backends (H2/H3/H4) ---
/// Blake2s-256 — the CPU-friendly ARX hash, Cirrus's default for native
/// symbolic execution on low-spec targets.
pub use crate::blake2s;
/// Ascon — the NIST-lightweight sponge: Ascon-Hash256 (cheap in-circuit) and
/// the Ascon-128a AEAD (the channels, replacing AES-GCM where it's a choice).
pub use crate::ascon;
/// Keccak/SHAKE128 — the on-chain backend (the native `KECCAK256` opcode).
pub use crate::keccak;

// --- The VOLE / OT / field surface Cirrus's `cirrus-volar-vole` consumes ---
pub use crate::field;
pub use crate::ot;
pub use crate::vole;

/// The hash backend selected for Cirrus's low-spec symbolic executors (native
/// speed in the executor is what matters there): Blake2s. The in-circuit
/// (recursive-proving / accumulator) choice is Ascon; on-chain stays Keccak.
///
/// This is a *marker* documenting the selection; the actual backend is chosen
/// per call site (H1's `Sponge`/`Digest` generics).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CirrusHashBackend {
    /// Blake2s (Cirrus-native default).
    Blake2s,
    /// Ascon (in-circuit / AEAD).
    Ascon,
    /// Keccak (on-chain).
    Keccak,
}

/// The default hash backend for Cirrus's low-spec symbolic executors.
pub const CIRrus_DEFAULT_HASH: CirrusHashBackend = CirrusHashBackend::Blake2s;

#[cfg(test)]
mod tests {
    /// Recompute the digest of the backing hash/cipher module sources and
    /// compare to the committed value — the drift check. On mismatch, print
    /// the new digest so the bindings can be regenerated. The sources are
    /// compile-time-included (`include_str!`), so a spec change forces a
    /// recompile and this test re-runs.
    #[test]
    fn cirrus_bindings_drift_check() {
        use super::blake2s::blake2s_256;
        let mut combined = alloc::vec::Vec::new();
        for src in [
            include_str!("blake2s.rs"),
            include_str!("ascon.rs"),
            include_str!("keccak.rs"),
        ] {
            combined.extend_from_slice(src.as_bytes());
        }
        let digest = blake2s_256(&combined);
        assert_eq!(
            digest,
            super::SPEC_HASH_SOURCES_DIGEST,
            "Cirrus bindings drift: the spec's hash/cipher modules changed. \
             Update SPEC_HASH_SOURCES_DIGEST and regenerate Cirrus's side."
        );
    }
}

/// The committed digest of the spec's hash/cipher module sources (blake2s.rs,
/// ascon.rs, keccak.rs) — the drift-check value. Updated when the bindings are
/// regenerated after a spec change.
pub const SPEC_HASH_SOURCES_DIGEST: [u8; 32] = [
    189, 135, 23, 134, 108, 248, 95, 76, 53, 231, 139, 133, 61, 87, 41, 93, 33, 0, 157, 124, 23,
    253, 232, 133, 4, 231, 73, 217, 42, 180, 173, 194,
];
